        "hide": "${ ('none' if (int(ndim) >= 1) else 'all') }"
      }
    },
    {
      "id": "dim2",
      "label": "Dimension 2",
      "dtype": "int",
      "default": "1",
      "options": [],
      "extra": {
        "hide": "${ ('none' if (int(ndim) >= 2) else 'all') }"
      }
    },
    {
      "id": "max_iterations",
