      "options": [],
      "extra": {}
    }
  ],
  "inputs": [],
  "outputs": [],
  "data_types": [
    "enum",
    "int",
    "raw"
  ],
  "domain": [],
  "implementation": [
    "show_id"
  ],
  "source_file": "C:\\Projects\\FlowPilot\\third_party\\gnuradio-main\\gnuradio-main\\gr-fec\\grc\\variable_ldpc_bit_flip_decoder.block.yml",
  "repository": "gnuradio-main",
  "module": "gr-fec",
  "version": null,
  "raw_metadata": {
    "id": "variable_ldpc_bit_flip_decoder_def",
    "label": "LDPC Bit Flip Decoder Definition",
    "flags": [
      "show_id"
    ],
    "parameters": [
      {
        "id": "value",
        "label": "Ignore Me",
        "dtype": "raw",
        "default": "\"ok\"",
        "hide": "all"
      },
      {
        "id": "ndim",
        "label": "Parallelism",
        "dtype": "enum",
        "options": [
          "0",
          "1",
          "2"
        ]
      },
      {
        "id": "dim1",
        "label": "Dimension 1",
        "dtype": "int",
        "default": "1",
        "hide": "${ ('none' if (int(ndim) >= 1) else 'all') }"
      },
      {
        "id": "dim2",
        "label": "Dimension 2",
        "dtype": "int",
        "default": "1",
        "hide": "${ ('none' if (int(ndim) >= 2) else 'all') }"
      },
      {
        "id": "max_iterations",
        "label": "Max Iterations",
        "dtype": "int",
        "default": "100"
      },
      {
        "id": "matrix_object",
        "label": "LDPC FEC Matrix ID",
        "dtype": "raw"
      }
    ],
    "value": "${ value }",
    "templates": {
      "imports": "from gnuradio import fec",
